-- Split líder × contribuidor individual dentro do nível (Caio #13). A Carolina
-- pediu os DOIS eixos: (1) flag de lideranca ("Liderança?" do cadastro) e (2) se
-- e gestor de pessoas (tem reporte direto na cadeia -- mesmo conceito do span).
-- Sao populacoes diferentes (ex.: lider sem reporte; gestor sem flag), por isso
-- guardamos as duas flags. Fonte: Talent Mobility (flag + cadeia de reporte),
-- casada por nome ao comp_ratio. As flags sao regravadas offline (UPDATE a partir
-- das listas do Talent Mobility); aqui so criamos as colunas.
ALTER TABLE public.comp_ratio ADD COLUMN IF NOT EXISTS is_leader boolean NOT NULL DEFAULT false;
ALTER TABLE public.comp_ratio ADD COLUMN IF NOT EXISTS is_people_manager boolean NOT NULL DEFAULT false;

